import pandas as pd
import numpy as np
from scipy import stats

# Load all available experiments
dfs = {}
for i in [1,2,4,5,6,7,8,9]:
    try:
        dfs[f"exp{i}"] = pd.read_csv(eval(f"experiment_{i}_csv"))
        print(f"\n=== Experiment {i} ===")
        print(f"Columns: {list(dfs[f'exp{i}'].columns)}")
        print(f"Shape: {dfs[f'exp{i}'].shape}")
        print(dfs[f"exp{i}"].describe().round(2))
    except Exception as e:
        print(f"\n=== Experiment {i}: Error === {e}")

# Combine all data for correlation analysis
all_data = []
for name, df in dfs.items():
    if 'JobThroughput' in df.columns:
        all_data.append(df)
combined = pd.concat(all_data, ignore_index=True) if all_data else None

if combined is not None and len(combined) > 0:
    print(f"\n=== COMBINED DATA ({len(combined)} rows) ===")
    # Check correlations with throughput
    for col in combined.columns:
        if combined[col].dtype in ['float64', 'int64']:
            r = combined[col].corr(combined['JobThroughput'])
            print(f"  {col} ~ JobThroughput: r = {r:.3f}")

    # Bin analysis for CoolingSetpoint
    if 'CoolingSetpoint' in combined.columns:
        print("\n--- CoolingSetpoint bins ---")
        for bin_label, lower, upper in [('Low', 0, 50), ('Mid', 50, 58), ('High', 58, 999)]:
            mask = (combined['CoolingSetpoint'] >= lower) & (combined['CoolingSetpoint'] < upper)
            if mask.sum() > 0:
                print(f"  {bin_label} ({lower}-{upper}): n={mask.sum()}, mean_throughput={combined.loc[mask,'JobThroughput'].mean():.2f}, sd={combined.loc[mask,'JobThroughput'].std():.2f}")

    # Bin analysis for FanSpeed
